import json, os, socket, sys
from pathlib import Path
base = Path('/Users/yunjinqi/Documents/new_projects/wt-iter65/bt_api_py/bt_api/bt_api_base')
tmp = Path('/private/tmp/iter65-base-expanded.0nt1fuq3')
stream = (tmp / 'events.jsonl').open('x', encoding='utf-8', buffering=1)
def emit(kind, **kw):
    stream.write(json.dumps({'kind': kind, **kw}, ensure_ascii=False) + '\n')
blocked = {'socket.connect', 'socket.bind', 'socket.getaddrinfo', 'socket.gethostbyname', 'socket.gethostbyaddr', 'socket.getnameinfo', 'subprocess.Popen', 'os.system', 'os.posix_spawn', 'os.spawn', 'os.fork', 'os.forkpty', 'os.exec'}
testing_guard = True
def guard(event, args):
    if event in blocked:
        if not testing_guard:
            emit('guard_blocked', event=event)
        raise PermissionError('offline guard blocked ' + event)
sys.addaudithook(guard)
for event in sorted(blocked):
    try: sys.audit(event)
    except PermissionError: pass
    else: raise RuntimeError('guard self-test failed: ' + event)
a, b = socket.socketpair(); a.send(b'x'); assert b.recv(1) == b'x'; a.close(); b.close()
testing_guard = False
sys.path.insert(0, str(base / 'src'))
import bt_api_base, pytest
assert Path(bt_api_base.__file__).resolve().is_relative_to(base / 'src')
emit('environment', python=sys.version, executable=sys.executable, pytest=pytest.__version__, base_import=bt_api_base.__file__, audit_self_test='all listed events blocked; socketpair works')
files = ['tests/test_http_retry.py','tests/test_account_protocol.py','tests/test_market_protocol.py','tests/test_market_history_protocol.py','tests/test_logging_factory_cold_start.py','tests/test_iter63_claim_fence.py','tests/test_iter63_claim_fence_coverage_seal.py','tests/containers/test_container_contract_v1.py','tests/test_thread_safety.py','tests/test_quality_batch_v4.py','tests/test_websocket_stop_lifecycle.py']
nodes = ['tests/test_service_protocol.py::test_transport_protocols_are_structural_and_service_protocol_import_is_stdlib_only','tests/test_wire_codec_v1.py::test_importing_the_contract_does_not_import_msgpack','tests/test_wire_account_codec.py::test_account_snapshot_cross_process_roundtrip','tests/test_wire_exit_gates.py::test_mixed_version_matrix_against_a_separate_old_process','tests/test_wire_strategy_commands.py::test_command_roundtrips_across_a_fresh_process']
args = ['-p', 'no:cacheprovider', '-p', 'pytest_asyncio.plugin', '--basetemp', str(tmp / 'pytest-tmp'), '-q'] + ['--ignore='+p for p in files] + ['--deselect='+n for n in nodes] + ['tests']
emit('configuration', args=args, ignored_files=files, deselected_nodes=nodes, blocked_audit_events=sorted(blocked))
class Recorder:
    def pytest_collection_modifyitems(self, items):
        emit('selected', nodeids=[i.nodeid for i in items])
    def pytest_deselected(self, items):
        emit('deselected', nodeids=[i.nodeid for i in items])
    def pytest_collectreport(self, report):
        if report.failed or report.skipped: emit('collection_report', nodeid=report.nodeid, outcome=report.outcome, detail=str(report.longrepr))
    def pytest_runtest_logreport(self, report):
        entry = dict(nodeid=report.nodeid, phase=report.when, outcome=report.outcome)
        if report.failed or report.skipped: entry['detail'] = str(report.longrepr)
        if hasattr(report, 'wasxfail'): entry['wasxfail'] = str(report.wasxfail)
        emit('phase', **entry)
    def pytest_warning_recorded(self, warning_message, when, nodeid, location):
        emit('warning', nodeid=nodeid, when=when, category=warning_message.category.__name__, message=str(warning_message.message), location=location)
try:
    code = int(pytest.main(args, plugins=[Recorder()]))
    emit('exit', code=code)
except BaseException as exc:
    emit('exception', type=type(exc).__name__, detail=str(exc))
    raise
finally:
    stream.close()

